exercises.solution:
const base = { a: 1, b: 2 };
const mid = Object.create(base);
mid.b = 20;
const leaf = Object.create(mid);

console.log('Q1:', leaf.a, "\u2014 inherited from base through mid");
console.log('Q2:', leaf.b, "\u2014 mid's own property shadows base.b");
console.log('Q3:', leaf.c, "\u2014 nowhere in the chain");
mid.a = 100;
console.log('Q4:', leaf.a, "\u2014 the link is live, not a copy; mutating base is visible via leaf");
console.log('Q5:', leaf.hasOwnProperty('b'), 'b' in leaf, "\u2014 'b' is not an own property of leaf, but is found via the chain");

