function myNew(Constructor, ...args) {
  // Step 1: fresh object; Step 2: link its [[Prototype]] to Constructor.prototype
  // Step 3: call Constructor with `this` = the fresh object
  // Step 4: if the call returned an object, use it; otherwise use the fresh object
}

function Person(name) { this.name = name; }
Person.prototype.greet = function () { return `hi, ${this.name}`; };

const p = myNew(Person, 'Ray');
console.log(p.name);
console.log(p.greet());
console.log(p instanceof Person);

function ReturnsObj() { this.x = 1; return { y: 2 }; }
const ro = myNew(ReturnsObj);
console.log(ro.y, ro.x);

function ReturnsPrim() { this.x = 1; return 42; }
console.log(myNew(ReturnsPrim).x);

exercises.solution:
function myNew(Constructor, ...args) {
  const obj = Object.create(Constructor.prototype); // steps 1 + 2
  const result = Constructor.apply(obj, args);      // step 3
  // Step 4: an object (or function) return wins; primitives are ignored.
  const isObject = result !== null &&
    (typeof result === 'object' || typeof result === 'function');
  return isObject ? result : obj;
}

function Person(name) { this.name = name; }
Person.prototype.greet = function () { return `hi, ${this.name}`; };

const p = myNew(Person, 'Ray');
console.log(p.name);
console.log(p.greet());
console.log(p instanceof Person);

function ReturnsObj() { this.x = 1; return { y: 2 }; }
const ro = myNew(ReturnsObj);
console.log(ro.y, ro.x);

function ReturnsPrim() { this.x = 1; return 42; }
console.log(myNew(ReturnsPrim).x);

exercises.starterCode:
function myInstanceof(obj, Ctor) {
  // Walk obj's chain with Object.getPrototypeOf, comparing each link
  // against Ctor.prototype. Return false for primitives/null/undefined.
}

class A {}
class B extends A {}
const b = new B();
const dict = Object.create(null);

function check(obj, Ctor, label) {
  const mine = myInstanceof(obj, Ctor);
  const native = obj instanceof Ctor;
  console.log(`${label}: my=${mine} native=${native}`);
  return mine === native;
}

let ok = true;
ok = check(b, B, 'b instanceof B') && ok;
ok = check(b, A, 'b instanceof A') && ok;
ok = check(b, Object, 'b instanceof Object') && ok;
ok = check(b, Array, 'b instanceof Array') && ok;
ok = check(5, Number, '5 instanceof Number') && ok;
ok = check(dict, Object, 'dict instanceof Object') && ok;
console.log('all match:', ok);

exercises.solution:
function myInstanceof(obj, Ctor) {
  if (obj === null || obj === undefined) return false;
  const t = typeof obj;
  if (t !== 'object' && t !== 'function') return false; // primitives have no chain
  const target = Ctor.prototype;
  let proto = Object.getPrototypeOf(obj);
  while (proto !== null) {
    if (proto === target) return true;
    proto = Object.getPrototypeOf(proto);
  }
  return false;
}

class A {}
class B extends A {}
const b = new B();
const dict = Object.create(null);

function check(obj, Ctor, label) {
  const mine = myInstanceof(obj, Ctor);
  const native = obj instanceof Ctor;
  console.log(`${label}: my=${mine} native=${native}`);
  return mine === native;
}

let ok = true;
ok = check(b, B, 'b instanceof B') && ok;
ok = check(b, A, 'b instanceof A') && ok;
ok = check(b, Object, 'b instanceof Object') && ok;
ok = check(b, Array, 'b instanceof Array') && ok;
ok = check(5, Number, '5 instanceof Number') && ok;
ok = check(dict, Object, 'dict instanceof Object') && ok;
console.log('all match:', ok);

exercises.prompt:
This hierarchy works, but it's the kind of taxonomy that rots — every new role forces a new branch. Refactor it to composition: small shared behavior units assembled per role, no `extends`.

```js
// The hierarchy to replace:
class Employee {
  constructor(name, pay) { this.name = name; this.pay = pay; }
  work() { return `${this.name} is working`; }
  getPay() { return this.pay; }
}
class Manager extends Employee {
  constructor(name, pay, teamSize) { super(name, pay); this.teamSize = teamSize; }
  holdMeeting() { return `${this.name} holds a standup for ${this.teamSize}`; }
}
class Engineer extends Employee {
  deploy() { return `${this.name} deploys to prod`; }
}
```

Your refactored code must satisfy these checks (the solution prints them):

```js
const mgr = makeManager('Ada', 120000, 5);
const eng = makeEngineer('Grace', 150000);
console.log(mgr.work());        // 'Ada is working'
console.log(mgr.getPay());      // 120000
console.log(mgr.holdMeeting()); // 'Ada holds a standup for 5'
console.log(eng.deploy());      // 'Grace deploys to prod'
console.log(eng.getPay());      // 150000
console.log(mgr.work === eng.work); // true — one shared unit, not duplicated
console.log(Object.getPrototypeOf(mgr) === Object.prototype); // true — flat, no hierarchy
```

Expected solution output:
```
Ada is working
120000
Ada holds a standup for 5
Grace deploys to prod
150000
true
true
ALL CHECKS PASSED
```

