exercises.solution:
const canWork = {
  work() { return `${this.name} is working`; }
};
const hasPay = {
  getPay() { return this.pay; }
};
const canManage = {
  holdMeeting() { return `${this.name} holds a standup for ${this.teamSize}`; }
};
const canDeploy = {
  deploy() { return `${this.name} deploys to prod`; }
};

function makeManager(name, pay, teamSize) {
  return Object.assign({ name, pay, teamSize }, canWork, hasPay, canManage);
}

function makeEngineer(name, pay) {
  return Object.assign({ name, pay }, canWork, hasPay, canDeploy);
}

const mgr = makeManager('Ada', 120000, 5);
const eng = makeEngineer('Grace', 150000);
const results = [
  mgr.work(),
  mgr.getPay(),
  mgr.holdMeeting(),
  eng.deploy(),
  eng.getPay(),
  mgr.work === eng.work,
  Object.getPrototypeOf(mgr) === Object.prototype
];
results.forEach(r => console.log(r));
const expected = ['Ada is working', 120000, 'Ada holds a standup for 5',
  'Grace deploys to prod', 150000, true, true];
console.log(results.every((r, i) => r === expected[i]) ? 'ALL CHECKS PASSED' : 'CHECKS FAILED');
